PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','admin')));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS venues(id INTEGER PRIMARY KEY,city TEXT NOT NULL CHECK(length(trim(city))>0),name TEXT NOT NULL CHECK(length(trim(name))>0),address TEXT NOT NULL,UNIQUE(city,name));
CREATE TABLE IF NOT EXISTS productions(id INTEGER PRIMARY KEY,title TEXT NOT NULL CHECK(length(trim(title))>0),description TEXT NOT NULL DEFAULT '',poster_url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY,production_id INTEGER NOT NULL REFERENCES productions(id),venue_id INTEGER NOT NULL REFERENCES venues(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=start_date),schedule_url TEXT NOT NULL DEFAULT '',seatmap_url TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)));
CREATE TABLE IF NOT EXISTS performances(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE,starts_at TEXT NOT NULL,cast_text TEXT NOT NULL DEFAULT '',UNIQUE(run_id,starts_at));
CREATE TABLE IF NOT EXISTS sale_rounds(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES runs(id) ON DELETE CASCADE,opens_at TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('priority','general')),note TEXT NOT NULL DEFAULT '',UNIQUE(run_id,opens_at,kind));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,url TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sale_channels(id INTEGER PRIMARY KEY,sale_round_id INTEGER NOT NULL REFERENCES sale_rounds(id) ON DELETE CASCADE,channel_id INTEGER NOT NULL REFERENCES channels(id),eligibility TEXT NOT NULL DEFAULT '',UNIQUE(sale_round_id,channel_id));
CREATE INDEX IF NOT EXISTS idx_sale_time ON sale_rounds(opens_at);
CREATE INDEX IF NOT EXISTS idx_runs_venue ON runs(venue_id);
CREATE TRIGGER IF NOT EXISTS performance_date_insert BEFORE INSERT ON performances BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM runs WHERE id=NEW.run_id AND substr(NEW.starts_at,1,10) BETWEEN start_date AND end_date) THEN RAISE(ABORT,'场次须在演出批次日期范围内') END; END;
CREATE TRIGGER IF NOT EXISTS performance_date_update BEFORE UPDATE ON performances BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM runs WHERE id=NEW.run_id AND substr(NEW.starts_at,1,10) BETWEEN start_date AND end_date) THEN RAISE(ABORT,'场次须在演出批次日期范围内') END; END;
CREATE TRIGGER IF NOT EXISTS run_date_update BEFORE UPDATE ON runs BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM performances WHERE run_id=OLD.id AND substr(starts_at,1,10) NOT BETWEEN NEW.start_date AND NEW.end_date) THEN RAISE(ABORT,'已有场次超出新日期范围') END; END;
